Func<Orc.Cards.CardEventView, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{
    if (view.Card is not Orc.Cards.Card played || !object.ReferenceEquals(played, view.Host))
    {
        return;
    }

    var runtime = Orc.Game.Effects.EffectRuntime.ResolveFor(played);
    if (runtime is null || ctx.Engine is null)
    {
        return;
    }

    ctx.Engine.Variables.TryGet<int>("diy.example3.destroyed", out var count);
    if (count <= 0)
    {
        return;
    }

    var owner = (played as Orc.Game.Cards.CardBase)?.Owner;
    var hq = owner?.Hq;
    if (hq is not null)
    {
        await runtime.BuffAsync(hq, 0, count, Orc.Game.Effects.EffectDuration.Permanent, ct, played);
    }
};

Func<Orc.Cards.CardEventView, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{
    if (ctx.Engine is null)
    {
        await Task.CompletedTask;
        return;
    }

    var variables = ctx.Engine.Variables;
    variables.TryGet<int>("diy.example3.destroyed", out var count);
    variables.Set("diy.example3.destroyed", count + 1);
    await Task.CompletedTask;
};
